sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    // Fetch the API data based on the structure you've provided
    const stages = api.data.sam_imp_home_1.output;
    // Generate HTML for each stage based on fetched data
    const generateStepHTML = (step) => {
        return `
        <div class="step">
            <img style="width: 32px; height: 32px" src="${step.headIcon}" />
            <div class="step-title">
                ${step.stage}
            </div>

            <div class="step-description">
                <div class="step-description-inner" style="max-height:50vh; overflow-y: auto; list-style-type: circle">
                    ${step.content}
                </div>

                <div class="down">
                    <svg xmlns="http://www.w3.org/2000/svg" height="32px" viewBox="0 -960 960 960" width="32px" fill="#000000">
                            <path d="M0-240v-63q0-43 44-70t116-27q13 0 25 .5t23 2.5q-14 21-21 44t-7 48v65H0Zm240 0v-65q0-32 17.5-58.5T307-410q32-20 76.5-30t96.5-10q53 0 97.5 10t76.5 30q32 20 49 46.5t17 58.5v65H240Zm540 0v-65q0-26-6.5-49T754-397q11-2 22.5-2.5t23.5-.5q72 0 116 26.5t44 70.5v63H780Zm-455-80h311q-10-20-55.5-35T480-370q-55 0-100.5 15T325-320ZM160-440q-33 0-56.5-23.5T80-520q0-34 23.5-57t56.5-23q34 0 57 23t23 57q0 33-23 56.5T160-440Zm640 0q-33 0-56.5-23.5T720-520q0-34 23.5-57t56.5-23q34 0 57 23t23 57q0 33-23 56.5T800-440Zm-320-40q-50 0-85-35t-35-85q0-51 35-85.5t85-34.5q51 0 85.5 34.5T600-600q0 50-34.5 85T480-480Zm0-80q17 0 28.5-11.5T520-600q0-17-11.5-28.5T480-640q-17 0-28.5 11.5T440-600q0 17 11.5 28.5T480-560Zm1 240Zm-1-280Z"></path>
                        </svg>
                        <ul>
                        ${step.Stakeholders.split(',').filter(contentData => contentData.trim() !== '').map((contentData) => {
                            return `<li>${contentData.trim()}.</li>`;
                    }).join('')}
                    </ul>
            </div>
            </div>
        </div>
    <div class="trapezoid trapezoid${step.stage === "Crawl" ? "1" : step.stage === "Walk" ? "2" : step.stage === "Run" ? "3" : step.stage === "Fly" ? "4" : ""}">
    ${step.output}
</div>
        `;
    };

    // Generate dynamic steps based on the fetched API data
    const stepsHTML = stages.map(generateStepHTML).join(""); // Map through the fetched data for stages

    return `
    <style>
     .down {
        background-color: #5555553a;
        display: flex;
        justify-content: center;
        flex-direction: column;
        align-items: center;
        border-radius: 5px;
        padding: 12px;
      }    
      ul{    
        padding-left:5px;
      }
        .steps-container {
            display: flex;
            justify-content: space-between;
            padding: 10px;
            flex-wrap: nowrap;
        }
        @media (max-width: 1238px) {
            .steps-container {
                justify-content: center;
            }
        }
        .trapezoid {
            flex: 1 1 calc(25.33% - 20px);
            max-width: calc(25.33% - 20px);
            box-sizing: border-box;
        }
        .step{
             flex: 1 1 calc(33.33% - 20px);
            max-width: calc(33.33% - 20px);
            box-sizing: border-box;
        }
        @media (max-width: 768px) {
            .step, .trapezoid {
                flex: 1 3 calc(50% - 20px);
                max-width: calc(50% - 20px);
            }
        }
        @media (max-width: 480px) {
            .step, .trapezoid {
                flex: 1 3 100%;
                max-width: 100%;
            }
        }
        .step {
            position: relative;
            background-color: #fff;
            border-radius: 8px;
            box-shadow: rgba(0, 0, 0, 0.05) 0px 6px 24px 0px, rgba(0, 0, 0, 0.08) 0px 0px 0px 1px;
            border: 2px solid #f4f4f4;
            padding: 15px;
            text-align: center;
        }
        .icon {
            position: absolute;
            left: 80%;
            top: 240px;
            transform: translateX(-50%);
        }
        .step-title {
            font-size: 16px;
            font-weight: bold;
            color: #333;
        }
        .step-description {
            font-size: 12px;
            color: #555;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            line-height: 1.4;
            height: 91%;
            text-align: left;
        }
        .trapezoid {
            height: auto;
            clip-path: polygon(0 0, 53% 0, 100% 50%, 53% 100%, 0 100%);
            line-height: 22px;
            color: #fff;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            gap: 10px;
            padding: 15px;
            flex: 1 1 calc(20.33% - 20px);
        }
        .trapezoid1 {
            background: #4F52BD;
        }
        .trapezoid2 {
            background: #3A3D88;
        }
        .trapezoid3 {
            background: #0f121b;
        }

    </style>

    <div class="steps-container">
        ${stepsHTML}
    </div>
    `;
}
